                                                                                                                                                                                                                                                                                                                                                                                                              end if;
                                                                                                                                                                                                                                                                                                                                                                                                                elsif tg_table_name = 'navigation_items' then
                                                                                                                                                                                                                                                                                                                                                                                                                    if new.title is distinct from old.title then
                                                                                                                                                                                                                                                                                                                                                                                                                          new.label := new.title;
                                                                                                                                                                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                                                                                                                                                                    new.title := new.label;
                                                                                                                                                                                                                                                                                                                                                                                                                                        end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                            if new.url is distinct from old.url then
                                                                                                                                                                                                                                                                                                                                                                                                                                                  new.href := new.url;
                                                                                                                                                                                                                                                                                                                                                                                                                                                      else
                                                                                                                                                                                                                                                                                                                                                                                                                                                            new.url := new.href;
