                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if new.display_order is distinct from old.display_order then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          new.sort_order := new.display_order;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    new.display_order := new.sort_order;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if new.is_visible is distinct from old.is_visible then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  new.is_enabled := new.is_visible;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            new.is_visible := new.is_enabled;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if new.open_in_new_tab is distinct from old.open_in_new_tab then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          new.is_external := new.open_in_new_tab;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    new.open_in_new_tab := new.is_external;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          elsif tg_table_name = 'user_admin_roles' then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if new.admin_role_id is distinct from old.admin_role_id then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    new.role_id := new.admin_role_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              new.admin_role_id := new.role_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return new;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $function$

CREATE OR REPLACE FUNCTION public.sync_project_comment_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    update public.projects set comment_count = comment_count + 1 where id = new.project_id;
    return new;
  elsif tg_op = 'DELETE' then
    update public.projects set comment_count = greatest(comment_count - 1, 0) where id = old.project_id;
    return old;
  end if;
  return null;
end; $function$

CREATE OR REPLACE FUNCTION public.sync_project_upvote_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    update public.projects set upvote_count = upvote_count + 1 where id = new.project_id;
    return new;
  elsif tg_op = 'DELETE' then
    update public.projects set upvote_count = greatest(upvote_count - 1, 0) where id = old.project_id;
    return old;
  end if;
  return null;
end; $function$
